def operation(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 0 # Or handle as per problem constraints, but for positive integers, this shouldn't happen immediately.

    d = n % 10  # The last digit
    n_prime = n // 10  # The remaining number
    n_new = n_prime + 3 * d
    return n_new

def simulate(start_n, steps):
    sequence = [start_n]
    current_n = start_n
    for _ in range(steps):
        current_n = operation(current_n)
        sequence.append(current_n)
    return sequence

# Test cases: 10, 19, 20, 29, 99
start_numbers = [10, 19, 20, 29, 99]
steps_to_check = 10 # Check for initial cycles

results = {}
for start_n in start_numbers:
    seq = simulate(start_n, steps_to_check)
    results[start_n] = seq

for start_n, seq in results.items():
    print(f"Start N={start_n}: {seq}")

